import React from 'react';
import { User, Code, GraduationCap } from 'lucide-react';

const StudentProfile = () => {
  return (
    <div className="p-8 text-right" dir="rtl">
      <div className="max-w-3xl mx-auto bg-white rounded-3xl p-8 shadow-sm">
        <div className="text-center mb-10">
          <div className="w-24 h-24 bg-blue-50 rounded-full mx-auto mb-4 flex items-center justify-center text-blue-600"><User size={48}/></div>
          <h2 className="text-xl font-bold">أيوب بن زينة</h2>
          <p className="text-slate-500">طالب في جامعة قسنطينة 2</p>
        </div>
        <div className="space-y-6">
          <div className="border-b pb-4"><h4 className="font-bold mb-2 flex items-center gap-2"><GraduationCap className="text-blue-600"/> التخصص</h4><p className="text-slate-600">Licence 3 - Technologie de l'information</p></div>
          <div><h4 className="font-bold mb-2 flex items-center gap-2"><Code className="text-blue-600"/> المهارات</h4>
            <div className="flex gap-2">{['React', 'Django', 'Tailwind'].map(s => <span className="bg-slate-100 px-3 py-1 rounded-lg text-sm">{s}</span>)}</div>
          </div>
        </div>
      </div>
    </div>
  );
};
export default StudentProfile;
